pub fn termination_proof_witness_for_node(n: Rc<Node>) -> Rc<Witness<Rc<TerminationProof>>> {
    crate::v2_std_node::fold_node(n, Rc::new(NodeFold {
    init: { Rc::new(move |n0| local_termination_proof_witness(n0.clone())) },
    step: { Rc::new(move |acc, e, child| termination_proof_fold_step(acc.clone(), e.clone(), child.clone())) },
    _phantom: std::marker::PhantomData,
}))
}

pub fn loop_bound_witness_for_node(n: Rc<Node>) -> Rc<Witness<Rc<LoopBound>>> {
    match (*loop_measure_node(n.clone())).clone() {
    Witness::Holds { value: measure, .. } => Rc::new(Witness::<Rc<LoopBound>>::Holds {
    value: Rc::new(LoopBound {
    measure: measure.clone(),
    termination: termination_proof_witness_for_node(n.clone()),
}),
}),
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<LoopBound>>::Violates {
    diagnostic: d.clone(),
}),
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum CardinalityConstraint {
    CardinalityImpossible,
    CardinalityBounded {
        interval: Rc<OrderedClosedInterval<i64>>,
    },
    CardinalityAtLeast {
        lower: i64,
    },
}

pub fn nat_le(a: Nat, b: Nat) -> bool {
    !(a.clone() > b.clone())
}

pub fn cardinality_exact(count: Nat) -> Rc<CardinalityConstraint> {
    Rc::new(CardinalityConstraint::CardinalityBounded {
    interval: crate::std_interval::degenerate_interval(count),
})
}

pub fn cardinality_between(low: Nat, high: Nat) -> Rc<CardinalityConstraint> {
    match (*crate::std_interval::closed_interval(low, high, nat_le)).clone() {
    IntervalConstruction::IntervalReady { interval: i, .. } => Rc::new(CardinalityConstraint::CardinalityBounded {
    interval: i.clone(),
}),
    IntervalConstruction::IntervalRefused { reason: _, .. } => Rc::new(CardinalityConstraint::CardinalityImpossible),
}
}

pub fn cardinality_lower(c: Rc<CardinalityConstraint>) -> Option<i64> {
    match (*c.clone()).clone() {
    CardinalityConstraint::CardinalityImpossible => std::option::Option::None,
    CardinalityConstraint::CardinalityBounded { interval: i, .. } => Some(crate::std_interval::interval_low(i.clone())),
    CardinalityConstraint::CardinalityAtLeast { lower: l, .. } => Some(l.clone()),
}
}

pub fn cardinality_map(c: Rc<CardinalityConstraint>) -> Rc<CardinalityConstraint> {
    c
}

pub fn cardinality_filter(c: Rc<CardinalityConstraint>) -> Rc<CardinalityConstraint> {
    match (*c.clone()).clone() {
    CardinalityConstraint::CardinalityImpossible => Rc::new(CardinalityConstraint::CardinalityImpossible),
    CardinalityConstraint::CardinalityBounded { interval: i, .. } => cardinality_between(0, crate::std_interval::interval_high(i.clone())),
    CardinalityConstraint::CardinalityAtLeast { lower: _, .. } => Rc::new(CardinalityConstraint::CardinalityAtLeast {
    lower: 0,
}),
}
}

pub fn cardinality_concat(a: Rc<CardinalityConstraint>, b: Rc<CardinalityConstraint>) -> Rc<CardinalityConstraint> {
    match (*a.clone()).clone() {
    CardinalityConstraint::CardinalityImpossible => Rc::new(CardinalityConstraint::CardinalityImpossible),
    CardinalityConstraint::CardinalityBounded { interval: ai, .. } => match (*b.clone()).clone() {
    CardinalityConstraint::CardinalityImpossible => Rc::new(CardinalityConstraint::CardinalityImpossible),
    CardinalityConstraint::CardinalityBounded { interval: bi, .. } => cardinality_between(crate::std_nat::nat_add(crate::std_interval::interval_low(ai.clone()), crate::std_interval::interval_low(bi.clone())), crate::std_nat::nat_add(crate::std_interval::interval_high(ai.clone()), crate::std_interval::interval_high(bi.clone()))),
    CardinalityConstraint::CardinalityAtLeast { lower: bl, .. } => Rc::new(CardinalityConstraint::CardinalityAtLeast {
    lower: crate::std_nat::nat_add(crate::std_interval::interval_low(ai.clone()), bl.clone()),
}),
},
    CardinalityConstraint::CardinalityAtLeast { lower: al, .. } => match (*b.clone()).clone() {
    CardinalityConstraint::CardinalityImpossible => Rc::new(CardinalityConstraint::CardinalityImpossible),
    CardinalityConstraint::CardinalityBounded { interval: bi, .. } => Rc::new(CardinalityConstraint::CardinalityAtLeast {
    lower: crate::std_nat::nat_add(al.clone(), crate::std_interval::interval_low(bi.clone())),
}),
    CardinalityConstraint::CardinalityAtLeast { lower: bl, .. } => Rc::new(CardinalityConstraint::CardinalityAtLeast {
    lower: crate::std_nat::nat_add(al.clone(), bl.clone()),
}),
},
}
}

pub fn cardinality_join(a: Rc<CardinalityConstraint>, b: Rc<CardinalityConstraint>) -> Rc<CardinalityConstraint> {
    match (*a.clone()).clone() {
    CardinalityConstraint::CardinalityImpossible => b.clone(),
    CardinalityConstraint::CardinalityBounded { interval: ai, .. } => match (*b.clone()).clone() {
    CardinalityConstraint::CardinalityImpossible => a.clone(),
    CardinalityConstraint::CardinalityBounded { interval: bi, .. } => cardinality_between(crate::std_nat::nat_min(crate::std_interval::interval_low(ai.clone()), crate::std_interval::interval_low(bi.clone())), crate::std_nat::nat_max(crate::std_interval::interval_high(ai.clone()), crate::std_interval::interval_high(bi.clone()))),
    CardinalityConstraint::CardinalityAtLeast { lower: bl, .. } => Rc::new(CardinalityConstraint::CardinalityAtLeast {
    lower: crate::std_nat::nat_min(crate::std_interval::interval_low(ai.clone()), bl.clone()),
}),
},
    CardinalityConstraint::CardinalityAtLeast { lower: al, .. } => match (*b.clone()).clone() {
    CardinalityConstraint::CardinalityImpossible => a.clone(),
    CardinalityConstraint::CardinalityBounded { interval: bi, .. } => Rc::new(CardinalityConstraint::CardinalityAtLeast {
    lower: crate::std_nat::nat_min(al.clone(), crate::std_interval::interval_low(bi.clone())),
}),
    CardinalityConstraint::CardinalityAtLeast { lower: bl, .. } => Rc::new(CardinalityConstraint::CardinalityAtLeast {
    lower: crate::std_nat::nat_min(al.clone(), bl.clone()),
}),
},
}
}

pub fn cardinality_proves_nonempty(c: Rc<CardinalityConstraint>) -> bool {
    match cardinality_lower(c) {
    std::option::Option::None => true,
    Some(l) => (0 < l.clone()),
}
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum CardinalityCountLaw {
    CountLiteralEmpty,
    CountPreserved,
    CountFloored,
    CountSummed,
    CountPlusOne,
    CountAtLeastZero,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CardinalityLawRow {
    pub operation: Symbol,
    pub law: CardinalityCountLaw,
}

pub fn cardinality_operation_laws() -> Rc<Vec<Rc<CardinalityLawRow>>> {
    thread_local! {
        static CACHED: Rc<Vec<Rc<CardinalityLawRow>>> = {
            Rc::new(vec![Rc::new(CardinalityLawRow {
    operation: "freemonoid_empty".to_string(),
    law: CardinalityCountLaw::CountLiteralEmpty,
}), Rc::new(CardinalityLawRow {
    operation: "list_append".to_string(),
    law: CardinalityCountLaw::CountSummed,
}), Rc::new(CardinalityLawRow {
    operation: "list_snoc_item".to_string(),
    law: CardinalityCountLaw::CountPlusOne,
}), Rc::new(CardinalityLawRow {
    operation: "list_map".to_string(),
    law: CardinalityCountLaw::CountPreserved,
}), Rc::new(CardinalityLawRow {
    operation: "list_reverse".to_string(),
    law: CardinalityCountLaw::CountPreserved,
}), Rc::new(CardinalityLawRow {
    operation: "collection_filter_shape".to_string(),
    law: CardinalityCountLaw::CountFloored,
}), Rc::new(CardinalityLawRow {
    operation: "collection_concat_shape".to_string(),
    law: CardinalityCountLaw::CountSummed,
}), Rc::new(CardinalityLawRow {
    operation: "list_flat_map".to_string(),
    law: CardinalityCountLaw::CountAtLeastZero,
})])
        };
    }
    CACHED.with(|c: &Rc<Vec<Rc<CardinalityLawRow>>>| c.clone())
}

pub fn cardinality_law_some(law: CardinalityCountLaw) -> Option<CardinalityCountLaw> {
    Some(law.clone())
}

pub fn cardinality_law_for(operation: std::string::String) -> Option<CardinalityCountLaw> {
    cardinality_operation_laws().iter().cloned().fold(std::option::Option::None, |acc: Option<CardinalityCountLaw>, row: Rc<CardinalityLawRow>| match acc.clone() {
    Some(_) => acc.clone(),
    std::option::Option::None => if (row.operation.clone() == operation.clone()) {
        cardinality_law_some(row.law.clone())
    } else {
        std::option::Option::None
    },
})
}

pub fn cardinality_apply_law(law: CardinalityCountLaw, operands: Rc<Vec<Rc<CardinalityConstraint>>>) -> Option<Rc<CardinalityConstraint>> {
    match law.clone() {
    CardinalityCountLaw::CountLiteralEmpty => { let __fm = operands.clone(); if __fm.is_empty() { Some(cardinality_exact(0)) } else { std::option::Option::None } },
    CardinalityCountLaw::CountPreserved => { let __fm = operands.clone(); if __fm.len() == 1 { let a = (*__fm)[0].clone(); Some(cardinality_map(a.clone())) } else { std::option::Option::None } },
    CardinalityCountLaw::CountFloored => { let __fm = operands.clone(); if __fm.len() == 1 { let a = (*__fm)[0].clone(); Some(cardinality_filter(a.clone())) } else { std::option::Option::None } },
    CardinalityCountLaw::CountSummed => { let __fm = operands.clone(); if __fm.len() == 2 { let a = (*__fm)[0].clone(); let b = (*__fm)[1].clone(); Some(cardinality_concat(a.clone(), b.clone())) } else { std::option::Option::None } },
    CardinalityCountLaw::CountPlusOne => { let __fm = operands.clone(); if __fm.len() == 1 { let a = (*__fm)[0].clone(); Some(cardinality_concat(a.clone(), cardinality_exact(1))) } else { std::option::Option::None } },
    CardinalityCountLaw::CountAtLeastZero => { let __fm = operands.clone(); if __fm.len() == 1 { let a = (*__fm)[0].clone(); match (*a.clone()).clone() {
    CardinalityConstraint::CardinalityImpossible => Some(Rc::new(CardinalityConstraint::CardinalityImpossible)),
    _ => Some(Rc::new(CardinalityConstraint::CardinalityAtLeast {
    lower: 0,
})),
} } else { std::option::Option::None } },
}
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct CountLiteralEmpty;
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct CountPreserved;
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct CountFloored;
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct CountSummed;
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct CountPlusOne;
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct CountAtLeastZero;
